package com.gameaggregator.webhookservice.application;import java.nio.charset.StandardCharsets;import java.security.*;import java.util.*;import javax.crypto.*;import javax.crypto.spec.*;import org.springframework.beans.factory.annotation.Value;import org.springframework.stereotype.Component;@Component public class WebhookSecretCipher{final SecretKey key;final SecureRandom random=new SecureRandom();public WebhookSecretCipher(@Value("${webhook.master-key}")String k){if(k.length()<32)throw new IllegalStateException("Webhook master key must have at least 32 characters");try{key=new SecretKeySpec(MessageDigest.getInstance("SHA-256").digest(k.getBytes(StandardCharsets.UTF_8)),"AES");}catch(Exception e){throw new IllegalStateException(e);}}public String encrypt(String raw){try{byte[] iv=new byte[12];random.nextBytes(iv);var c=Cipher.getInstance("AES/GCM/NoPadding");c.init(Cipher.ENCRYPT_MODE,key,new GCMParameterSpec(128,iv));byte[] out=c.doFinal(raw.getBytes(StandardCharsets.UTF_8)),all=new byte[iv.length+out.length];System.arraycopy(iv,0,all,0,iv.length);System.arraycopy(out,0,all,iv.length,out.length);return Base64.getEncoder().encodeToString(all);}catch(Exception e){throw new IllegalStateException(e);}}public String decrypt(String value){try{byte[] all=Base64.getDecoder().decode(value),iv=Arrays.copyOfRange(all,0,12),data=Arrays.copyOfRange(all,12,all.length);var c=Cipher.getInstance("AES/GCM/NoPadding");c.init(Cipher.DECRYPT_MODE,key,new GCMParameterSpec(128,iv));return new String(c.doFinal(data),StandardCharsets.UTF_8);}catch(Exception e){throw new IllegalStateException(e);}}}